from functools import lru_cache

def find_permutation(nums):
    n = len(nums)
    full = (1 << n) - 1

    # dp(mask, last): min cost to place the remaining values after `last`
    # and close the cycle back to perm[0] = 0 (closing edge: |last - nums[0]|)
    @lru_cache(maxsize=None)
    def dp(mask, last):
        if mask == full:
            return abs(last - nums[0])
        best = float('inf')
        for nxt in range(n):
            if not (mask >> nxt) & 1:
                best = min(best, abs(last - nums[nxt]) + dp(mask | (1 << nxt), nxt))
        return best

    # Rotation does not change the score, so the lexicographically smallest answer starts with 0.
    perm = [0]
    mask, last = 1, 0
    while mask != full:
        target = dp(mask, last)
        for nxt in range(n):  # smallest next value that keeps the cost optimal
            if not (mask >> nxt) & 1 and abs(last - nums[nxt]) + dp(mask | (1 << nxt), nxt) == target:
                perm.append(nxt)
                mask |= 1 << nxt
                last = nxt
                break
    return perm
